begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
insert into auth.users(id) values
 ('20000000-0000-0000-0000-000000000001'),('20000000-0000-0000-0000-000000000002'),
 ('20000000-0000-0000-0000-000000000003'),('20000000-0000-0000-0000-000000000004'),('20000000-0000-0000-0000-000000000005');
insert into public.user_roles values ('20000000-0000-0000-0000-000000000003','therapist'),('20000000-0000-0000-0000-000000000004','therapist'),('20000000-0000-0000-0000-000000000005','admin');
insert into public.therapist_patients(therapist_id,patient_id) values ('20000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001');
insert into public.exercises(id,code,active) values('30000000-0000-0000-0000-000000000001','test-only',true);
insert into public.exercise_versions(id,exercise_id,version,algorithm_key,definition,published) values('30000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000001',1,'test-only','{}',true);
insert into public.exercise_assignments(id,patient_id,therapist_id) values('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000003');
insert into public.prescription_versions(id,assignment_id,patient_id,exercise_version_id,version,side,minimum_degrees,maximum_degrees,target_repetitions,created_by) values('30000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',1,'left',10,90,5,'20000000-0000-0000-0000-000000000003');
insert into public.sessions values('30000000-0000-0000-0000-000000000005','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004',now(),now(),'completed','test','test','test');
insert into public.session_measurements(session_id,metric_key,side,minimum_degrees,maximum_degrees,completed_repetitions,quality) values('30000000-0000-0000-0000-000000000005','elbow','left',10,90,5,'valid');
select throws_ok($$update public.prescription_versions set target_repetitions=9$$,'P0001',null,'prescription history is immutable');
select throws_ok($$insert into public.session_measurements(session_id,metric_key,side,minimum_degrees,maximum_degrees,completed_repetitions,quality) values('30000000-0000-0000-0000-000000000005','negative-test','left',10,90,-1,'valid')$$,'23514',null,'negative repetition count rejected');
select throws_ok($$insert into public.sessions values('30000000-0000-0000-0000-000000000006','20000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000004',now(),now(),'completed','test','test','test')$$,'23503',null,'cross-patient prescription reference rejected');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((select count(*)::integer from public.patients),1,'patient sees self only');
select is((select count(*)::integer from public.session_measurements),1,'patient sees own measurement');
select throws_ok($$insert into public.user_roles values(auth.uid(),'admin')$$,'42501',null,'cannot self-promote');
select throws_ok($$update public.profiles set active=false where id=auth.uid()$$,'42501',null,'cannot change protected profile fields');
select throws_ok($$update public.prescription_versions set target_repetitions=50$$,'42501',null,'patient cannot edit prescription');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from public.sessions),0,'patient B cannot see A sessions');
select is((select count(*)::integer from public.session_measurements),0,'patient B cannot see child measurements');
select throws_ok($$insert into public.consents(patient_id,consent_type,version,event) values('20000000-0000-0000-0000-000000000001','test','1','granted')$$,'42501',null,'patient B cannot write A consent');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
select is((select count(*)::integer from public.sessions),1,'assigned therapist sees patient sessions');
select is((select count(*)::integer from public.session_measurements),1,'assigned therapist sees child measurements');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select is((select count(*)::integer from public.sessions),0,'unassigned therapist sees no sessions');
select is((select count(*)::integer from public.session_measurements),0,'unassigned therapist sees no measurements');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000005',true);
select is((select count(*)::integer from public.sessions),1,'admin can review sessions');
set local role anon;
select throws_ok($$select * from public.sessions$$,'42501',null,'anonymous has no sessions access');
reset role;
update public.therapist_patients set active=false;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
select is((select count(*)::integer from public.sessions),0,'revoked therapist loses access');
select * from finish();
rollback;
